import{_ as a,o as i,c as e,a4 as t}from"./chunks/framework.BBs01uty.js";const k=JSON.parse('{"title":"Reconciler 协调器","description":"","frontmatter":{},"headers":[],"relativePath":"react/reconciler.md","filePath":"react/reconciler.md"}'),n={name:"react/reconciler.md"};function l(o,s,p,r,d,h){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="reconciler-协调器" tabindex="-1">Reconciler 协调器 <a class="header-anchor" href="#reconciler-协调器" aria-label="Permalink to &quot;Reconciler 协调器&quot;">​</a></h1><p>Reconciler 是 React 渲染流程的核心引擎，负责将 JSX 描述转化为实际的 DOM 操作。它的工作分为两个阶段：<strong>beginWork（递）</strong> 和 <strong>completeWork（归）</strong>，按照 DFS（深度优先）顺序遍历 Fiber 树。</p><blockquote><p>本篇是 Reconciler 的总览，后续 <a href="./reconcile-algorithm.html">Reconcile 算法</a> 会深入 diff 细节，<a href="./commit.html">Commit 阶段</a> 会讲解 DOM 操作。</p></blockquote><h2 id="整体流程" tabindex="-1">整体流程 <a class="header-anchor" href="#整体流程" aria-label="Permalink to &quot;整体流程&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;从 rootFiber 开始&quot;] --&gt; B[&quot;beginWork 递&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C{&quot;有子节点?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|是| D[&quot;处理子节点 beginWork&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|否| E[&quot;completeWork 归&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F{&quot;有兄弟节点?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt;|是| G[&quot;兄弟节点 beginWork&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt;|否| H[&quot;父节点 completeWork&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    H --&gt; F</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style B fill:#e1f5ff</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style E fill:#d4edda</span></span></code></pre></div><p>一句话概括：<strong>beginWork 从根往下走，遇到叶子就折返；completeWork 从叶子往上走，有兄弟就拐过去继续递。如此交替，直到回到根节点。</strong></p><hr><h2 id="flag-副作用标记" tabindex="-1">Flag：副作用标记 <a class="header-anchor" href="#flag-副作用标记" aria-label="Permalink to &quot;Flag：副作用标记&quot;">​</a></h2><p>Flag 用 32 位二进制数的不同位来追踪副作用，例如：</p><table tabindex="0"><thead><tr><th>Flag</th><th>含义</th></tr></thead><tbody><tr><td>Placement</td><td>节点需要插入或移动</td></tr><tr><td>Update</td><td>节点属性需要更新</td></tr><tr><td>Deletion</td><td>节点需要删除</td></tr><tr><td>ChildDeletion</td><td>子节点需要删除</td></tr></tbody></table><p>使用位运算（<code>|=</code>）可以高效地合并多个 flag，这也是 React 选择位标记而非数组的原因——性能好、内存占用小。</p><hr><h2 id="beginwork-递" tabindex="-1">beginWork（递） <a class="header-anchor" href="#beginwork-递" aria-label="Permalink to &quot;beginWork（递）&quot;">​</a></h2><p>beginWork 分 <strong>mount</strong> 和 <strong>update</strong> 两条路径，核心区别在于 <strong>update 阶段需要追踪 effect flag</strong>，而 mount 阶段基本不追踪。</p><h3 id="mount-路径" tabindex="-1">mount 路径 <a class="header-anchor" href="#mount-路径" aria-label="Permalink to &quot;mount 路径&quot;">​</a></h3><ol><li>根据 <code>wip.tag</code>（Fiber 节点类型）进入对应的处理函数</li><li>调用 <code>mountChildFibers</code> 执行 reconcile 算法，得到子 FiberNode</li></ol><blockquote><p><strong>wip</strong> 是 <code>workInProgress</code> 的缩写，指当前正在构建的 Fiber 节点。</p></blockquote><h3 id="update-路径" tabindex="-1">update 路径 <a class="header-anchor" href="#update-路径" aria-label="Permalink to &quot;update 路径&quot;">​</a></h3><ol><li>判断当前 Fiber 是否可以复用（命中 bailout 优化），复用则走优化路径跳过 diff</li><li>根据 <code>wip.tag</code> 进入对应的处理函数</li><li>调用 <code>reconcileChildFibers</code> 执行 reconcile 算法，得到<strong>带 flag</strong> 的子 FiberNode</li></ol><blockquote><p><strong>注意区分两个 &quot;diff&quot;：</strong> beginWork 阶段的 reconcile 算法（详见 <a href="./reconcile-algorithm.html">Reconcile 算法</a>）对比的是<strong>子节点</strong>——决定哪些子 Fiber 复用/新建/删除。而 completeWork 阶段的 <code>diffProperties</code> 对比的是<strong>当前节点自身的 DOM 属性</strong>（如 className、style）——决定哪些 HTML 属性需要更新。两者发生在不同阶段，操作对象不同。</p></blockquote><h3 id="mount-为什么不追踪-flag" tabindex="-1">mount 为什么不追踪 flag？ <a class="header-anchor" href="#mount-为什么不追踪-flag" aria-label="Permalink to &quot;mount 为什么不追踪 flag？&quot;">​</a></h3><p>这是一个关键的性能优化设计。mount 阶段的 HostRootFiber 因为有 alternate（双缓存机制），会进入 update 处理逻辑，所以它会被标记 Placement。但它的子树全部走 mount 路径，<strong>不会标记任何 flag</strong>。</p><p>为什么这样做？因为 mount 阶段会在内存中组装好一棵完整的离屏 DOM 树，commit 阶段只需要<strong>一次</strong> <code>appendChild</code> 就把整棵子树插入页面。如果 mount 阶段也给每个节点标记 Placement，commit 阶段就会对每个节点都执行一次插入操作，性能很差。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;HostRootFiber&quot;] --&gt;|标记 Placement| B[&quot;commit 时插入&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt; C[&quot;子 Fiber A&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt; D[&quot;子 Fiber B&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; E[&quot;子 Fiber A-1&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; F[&quot;子 Fiber A-2&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; G[&quot;子 Fiber B-1&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style A fill:#ffe1e1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style C fill:#d4edda</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style D fill:#d4edda</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style E fill:#d4edda</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style F fill:#d4edda</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style G fill:#d4edda</span></span></code></pre></div><p><strong>总结：mount 阶段只有 HostRootFiber 有 flag，其他子 Fiber 都没有。离屏组装好 DOM 树后，commit 阶段一次挂载，这是性能优化的考量。</strong></p><h3 id="mountchildfibers-vs-reconcilechildfibers" tabindex="-1">mountChildFibers vs reconcileChildFibers <a class="header-anchor" href="#mountchildfibers-vs-reconcilechildfibers" aria-label="Permalink to &quot;mountChildFibers vs reconcileChildFibers&quot;">​</a></h3><p>这两个函数实际上调用的是同一个 <code>ChildReconciler(shouldTrackSideEffects)</code>，只是传参不同：</p><ul><li><code>mountChildFibers</code> → <code>shouldTrackSideEffects = false</code>（不追踪 flag）</li><li><code>reconcileChildFibers</code> → <code>shouldTrackSideEffects = true</code>（追踪 flag）</li></ul><hr><h2 id="completework-归" tabindex="-1">completeWork（归） <a class="header-anchor" href="#completework-归" aria-label="Permalink to &quot;completeWork（归）&quot;">​</a></h2><p>completeWork 是&quot;归&quot;的阶段，从叶节点开始自下而上处理。</p><h3 id="mount-路径-1" tabindex="-1">mount 路径 <a class="header-anchor" href="#mount-路径-1" aria-label="Permalink to &quot;mount 路径&quot;">​</a></h3><ol><li><strong>createInstance</strong>：创建 DOM 实例</li><li><strong>appendAllChildren</strong>：将子节点的 DOM 挂载到刚创建的 DOM 上</li><li><strong>设置 DOM 属性</strong>：如 className、style 等</li><li><strong>flag 冒泡</strong>：将子树的副作用标记向上传递</li></ol><h4 id="appendallchildren-详解" tabindex="-1">appendAllChildren 详解 <a class="header-anchor" href="#appendallchildren-详解" aria-label="Permalink to &quot;appendAllChildren 详解&quot;">​</a></h4><p>appendAllChildren 的目的是在离屏状态下把子节点的 DOM 都挂到父节点上，这样 commit 阶段只需一次插入操作。</p><p>它的遍历逻辑是深度优先的：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;从当前 Fiber 往下&quot;] --&gt; B[&quot;找到第一层 Host 节点&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;appendChild 到父 DOM&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;处理兄弟 Fiber&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E{&quot;有兄弟?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|是| B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|否| F[&quot;回到父级的兄弟&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; G{&quot;有父级兄弟?&quot;}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt;|是| B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G --&gt;|否| H[&quot;回到起点，结束&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style B fill:#e1f5ff</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style H fill:#d4edda</span></span></code></pre></div><p>举个例子，假设 Fiber 树结构是 <code>div &gt; (span + p &gt; em)</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>div                    ← createInstance(&quot;div&quot;)</span></span>
<span class="line"><span>├── span               ← createInstance(&quot;span&quot;)</span></span>
<span class="line"><span>│                      ← appendChild(div, span)</span></span>
<span class="line"><span>└── p                  ← createInstance(&quot;p&quot;)</span></span>
<span class="line"><span>    └── em             ← createInstance(&quot;em&quot;)</span></span>
<span class="line"><span>                       ← appendChild(p, em)</span></span>
<span class="line"><span>                       ← appendChild(div, p)</span></span></code></pre></div><p>最终离屏 DOM 树组装完成，commit 阶段把 <code>div</code> 一次性插入页面即可。</p><h3 id="update-路径-1" tabindex="-1">update 路径 <a class="header-anchor" href="#update-路径-1" aria-label="Permalink to &quot;update 路径&quot;">​</a></h3><ol><li><strong>diffProperties</strong>：对比新旧属性，标记需要更新/删除的属性</li><li><strong>flag 冒泡</strong></li></ol><h4 id="diffproperties-属性更新" tabindex="-1">diffProperties（属性更新） <a class="header-anchor" href="#diffproperties-属性更新" aria-label="Permalink to &quot;diffProperties（属性更新）&quot;">​</a></h4><p>分两次遍历：</p><ol><li><strong>第一次遍历旧属性</strong>：找出旧节点存在但新节点不存在的属性 → 标记删除</li><li><strong>第二次遍历新属性</strong>：找出新旧都存在的属性 → 标记更新</li></ol><p>最终将需要更新的属性以 <code>[key1, val1, key2, val2, ...]</code> 的数组形式存在 <code>fiberNode.updateQueue</code> 中，commit 阶段统一应用。</p><hr><h2 id="flags-冒泡" tabindex="-1">Flags 冒泡 <a class="header-anchor" href="#flags-冒泡" aria-label="Permalink to &quot;Flags 冒泡&quot;">​</a></h2><p>completeWork 阶段属于&quot;归&quot;的过程，从叶元素开始自下而上将子孙的 flags 汇总到父节点。使用位运算简化代码并提升性能：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 收集子元素的子孙元素的 flags</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">subtreeFlags </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> child.subtreeFlags</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 收集子元素自身的 flags</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">subtreeFlags </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> child.flags</span></span></code></pre></div><p>冒泡的结果是：根节点的 <code>subtreeFlags</code> 包含了整棵树中所有需要处理的副作用类型，根节点的 <code>flags</code> 包含根节点自身的副作用。commit 阶段可以根据这些标记快速定位需要操作的节点，而不必遍历整棵树。</p><hr><h2 id="与后续章节的关系" tabindex="-1">与后续章节的关系 <a class="header-anchor" href="#与后续章节的关系" aria-label="Permalink to &quot;与后续章节的关系&quot;">​</a></h2><ul><li>beginWork 中的 reconcile 算法（diff）→ 详见 <a href="./reconcile-algorithm.html">Reconcile 算法</a></li><li>completeWork 构建好的 Fiber 树如何变成真实 DOM → 详见 <a href="./commit.html">Commit 阶段</a></li><li>状态更新如何触发 Reconciler 工作 → 详见 <a href="./state-update.html">状态更新流程</a></li></ul>`,54)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
